INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38311, 'Leviticus 11:21', 'Leviticus', 11, 21, 'بې له هغو حشراتو څخه چې ټوپونه وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_21.mp3', '', 1761754199, 1761754199),
(38312, 'Leviticus 11:22', 'Leviticus', 11, 22, 'د هغو څخه کولای شئ چې ډول ډول چورچورکۍ او ملخان وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_22.mp3', '', 1761754199, 1761754199),
(38313, 'Leviticus 11:23', 'Leviticus', 11, 23, 'خو نور ټول وزر لرونکي حشرات چې په پښو باندې هم ګرځي، باید حرام وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_23.mp3', '', 1761754199, 1761754199),
(38314, 'Leviticus 11:29', 'Leviticus', 11, 29, 'د هغو حیواناتو څخه چې په ځمکه باندې ګرځي، دغه حیوانات ستاسو دپاره ناپاک دي: ړنده مږه، موږک، هر ډول سمساره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_29.mp3', '', 1761754199, 1761754199),
(38315, 'Leviticus 11:30', 'Leviticus', 11, 30, 'ډول ډول د کور او د شګې چرمښکۍ او کربوړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_30.mp3', '', 1761754199, 1761754199),
(38316, 'Leviticus 11:31', 'Leviticus', 11, 31, 'هرڅوک چې د هغو مړو ته لاس وروړي، هغه به تر ماښامه پورې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_31.mp3', '', 1761754199, 1761754199),
(38317, 'Leviticus 11:32', 'Leviticus', 11, 32, 'که چېرې د هغو مړي په یو شي باندې ولویږي، هغه شی به ناپاک شي. همداسې کار به د لرګي، ټوکر، څرمنې، یا بوجۍ په موادو باندې کیږي او مهمه نه ده چې هغه د څه شي دپاره کارول کیږي. هغه دې په اوبو کې غوټه کړای شي، خو تر ماښامه پورې به ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_32.mp3', '', 1761754199, 1761754199),
(38318, 'Leviticus 11:33', 'Leviticus', 11, 33, 'که چېرې د هغو مړي د خټې په یو لوښي کې وغورځیږي، هرڅه چې په هغه کې دي ناپاک به شي او تاسو باید هغه لوښی مات کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_33.mp3', '', 1761754199, 1761754199),
(38319, 'Leviticus 11:34', 'Leviticus', 11, 34, 'کوم خواړه چې په عادي توګه حلال وي، خو که د داسې لوښي څخه په هغو خوړو باندې اوبه توی شي، هغه به ناپاک شي او د څښلو هرڅه چې په دې لوښي کې وي، هغه ناپاک دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_34.mp3', '', 1761754199, 1761754199),
(38320, 'Leviticus 11:35', 'Leviticus', 11, 35, 'په هر شي باندې چې د هغو مړي ولویږي هغه شی ناپاکه کیږي، که په هغو کې نغری یا د پخلي لوښی شامل وي، هغه باید مات شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_35.mp3', '', 1761754199, 1761754199),
(38321, 'Leviticus 11:36', 'Leviticus', 11, 36, 'خو یوه چینه یا څاه چې دغه مړه حیوانات په کې پراته وي، هغه پاک پاتې کیږي. خو هرڅوک چې د دغو مړو له جملې څخه کوم یو ته لاس وروړي، هغه به ناپاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_36.mp3', '', 1761754199, 1761754199),
(38322, 'Leviticus 11:37', 'Leviticus', 11, 37, 'که چېرې یو داسې مړی په هغو تخمونو باندې وغورځیږي چې کرل کیږي، هغه تخمونه پاک پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_37.mp3', '', 1761754199, 1761754199),
(38323, 'Leviticus 11:38', 'Leviticus', 11, 38, 'خو که چېرې په تخمونو باندې اوبه توی شوې وي او په هغه باندې یو داسې مړی ولویږي، نو هغه ستاسو دپاره ناپاک دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_38.mp3', '', 1761754199, 1761754199),
(38324, 'Leviticus 11:39', 'Leviticus', 11, 39, 'که چېرې یو حیوان چې ستاسو دپاره پاک وي مړ شي، هرڅوک چې د هغه مړي ته لاس وروړي هغه به تر ماښامه پورې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_39.mp3', '', 1761754199, 1761754199),
(38325, 'Leviticus 11:40', 'Leviticus', 11, 40, 'هرڅوک چې د دې مړ حیوان د غوښې څخه لږه غوښه وخوري، باید خپل کالي ووینځي، خو هغه به تر ماښامه پورې ناپاک وي. هرڅوک چې د هغه مړی راپورته کړي، هغه باید خپل کالي ووینځي، خو هغه به تر ماښامه پورې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_40.mp3', '', 1761754199, 1761754199),
(38326, 'Leviticus 11:41', 'Leviticus', 11, 41, 'هره خزنده چې په ځمکه باندې ګرځي، باید ونه خوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_41.mp3', '', 1761754199, 1761754199),
(38327, 'Leviticus 11:42', 'Leviticus', 11, 42, 'ستاسو دپاره هره خزنده حرامه ده، که هغه په سینه باندې ښوییږي یا په څلورو یا په ډېرو پښو ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_42.mp3', '', 1761754199, 1761754199),
(38328, 'Leviticus 11:43', 'Leviticus', 11, 43, 'د هغو څخه د کوم یو په خوړلو سره خپل ځانونه مه ناپاکه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_43.mp3', '', 1761754199, 1761754199),
(38329, 'Leviticus 11:44', 'Leviticus', 11, 44, 'زه ستاسو څښتن خدای یم، تاسو باید خپل ځانونه پاک کړئ او سپېڅلي اوسئ، ځکه چې زه سپېڅلی یم. خپل ځانونه په هېڅ یوې خزندې باندې مه ناپاکه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_44.mp3', '', 1761754199, 1761754199),
(38330, 'Leviticus 11:45', 'Leviticus', 11, 45, 'زه څښتن یم چې تاسو مې د مصر څخه راوویستلئ، ترڅو ستاسو خدای اوسم. له دې امله تاسو باید سپېڅلي اوسئ، ځکه چې زه سپېڅلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_45.mp3', '', 1761754199, 1761754199),
(38331, 'Leviticus 11:46', 'Leviticus', 11, 46, 'دا قوانین د حیواناتو، مرغانو او هرڅه چې په اوبو کې ژوند کوي او ټولو خزندو په اړه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_46.mp3', '', 1761754199, 1761754199),
(38332, 'Leviticus 11:47', 'Leviticus', 11, 47, 'تاسو باید پام وکړئ چې د پاک او ناپاک او همدارنګه د حلالو او حرامو حیواناتو ترمنځ فرق وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus11_verse_47.mp3', '', 1761754199, 1761754199),
(38333, 'Leviticus 26:1', 'Leviticus', 26, 1, 'څښتن وویل: «د خپلو ځانونو دپاره بتان، مجسمې یا د تیږو ستنې مه جوړوئ چې د هغو عبادت وکړئ. زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_1.mp3', '', 1761754199, 1761754199),
(38334, 'Leviticus 26:2', 'Leviticus', 26, 2, 'د سبت د ورځې څخه پیروي وکړئ او د هغه ځای درناوی وکړئ چې زما عبادت په کې کیږي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_2.mp3', '', 1761754199, 1761754199),
(38335, 'Leviticus 26:3', 'Leviticus', 26, 3, 'که چېرې تاسو زما د فرمانونو څخه پیروي وکړئ او زما امرونو ته غاړه کېږدئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_3.mp3', '', 1761754199, 1761754199),
(38336, 'Leviticus 26:4', 'Leviticus', 26, 4, 'نو زه به په سم وخت په تاسو باندې باران ووروم، ترڅو ځمکه حاصلات ورکړي او ونې مېوې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_4.mp3', '', 1761754199, 1761754199),
(38337, 'Leviticus 26:5', 'Leviticus', 26, 5, 'ستاسو فصلونه به دومره پرېمانه شي چې ستاسو د غلو دانو غوبل به تر هغې پورې دوام وکړي، ترڅو د انګورو د راټولولو وخت راشي او ستاسو د انګورو د حاصل راټولول به تر هغه وخته پورې دوام وکړي، ترڅو د غلو دانو د کرلو وخت راورسیږي. هرڅه چې تاسو یې غواړئ، هغه به وخورئ او په خپله خاوره کې به په امن سره واوسېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_5.mp3', '', 1761754199, 1761754199),
(38338, 'Leviticus 26:6', 'Leviticus', 26, 6, 'زه به ستاسو خاورې ته ارامي راولم او تاسو به بې د چا له وېرې خوب کولای شئ. زه به د هغې خاورې څخه خطرناک حیوانات لېرې کړم او هلته به نور جنګ نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_6.mp3', '', 1761754199, 1761754199),
(38339, 'Leviticus 26:7', 'Leviticus', 26, 7, 'تاسو به په خپلو دښمنانو باندې بریالي شئ او په جګړه کې به یې ووژنئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_7.mp3', '', 1761754199, 1761754199),
(38340, 'Leviticus 26:8', 'Leviticus', 26, 8, 'ستاسو پنځه تنه به وکولای شي چې سلو تنو ته ماتې ورکړي او ستاسو سل تنه به وکولای شي چې لسو زرو تنو ته ماتې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_8.mp3', '', 1761754199, 1761754199),
(38341, 'Leviticus 26:9', 'Leviticus', 26, 9, 'زه به تاسو ته برکت درکړم او ډېر اولادونه به درکړم او په هغه لوظ باندې به ودرېږم چې تاسو سره مې کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_9.mp3', '', 1761754199, 1761754199),
(38342, 'Leviticus 26:10', 'Leviticus', 26, 10, 'ستاسو حاصلات به دومره پرېمانه شي چې هغه به تر کاله پورې ورسیږي او حتی څه چې د زاړه حاصل څخه پاتې دي هغه به لېرې وغورځوئ، ترڅو د نوي حاصل دپاره ځای پیدا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_10.mp3', '', 1761754199, 1761754199),
(38343, 'Leviticus 26:11', 'Leviticus', 26, 11, 'زه به راشم او ستاسو په منځ کې به اوسېږم او هېڅکله به ستاسو څخه کرکه ونه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_11.mp3', '', 1761754199, 1761754199),
(38344, 'Leviticus 26:12', 'Leviticus', 26, 12, 'زه به تاسو سره مل یم او ستاسو خدای به یم او تاسو به زما قوم یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_12.mp3', '', 1761754199, 1761754199),
(38345, 'Leviticus 26:13', 'Leviticus', 26, 13, 'زه ستاسو څښتن خدای یم چې تاسو مې د مصر څخه راوویستلئ، ترڅو نور د مصریانو غلامان ونه اوسئ. ما ستاسو د غلامۍ جغونه مات کړل او تاسو ته مې د دې توان درکړ چې په سرلوړۍ سره واوسېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_13.mp3', '', 1761754199, 1761754199),
(38346, 'Leviticus 26:14', 'Leviticus', 26, 14, 'څښتن وویل: «خو که چېرې زما امرونو ته غاړه کېنږدئ، نو تاسو ته به سزا درکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_14.mp3', '', 1761754199, 1761754199),
(38347, 'Leviticus 26:15', 'Leviticus', 26, 15, 'که چېرې تاسو زما د قوانینو او حکمونو د منلو څخه انکار وکړئ او هغه لوظ مات کړئ چې تاسو سره مې کړی دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_15.mp3', '', 1761754199, 1761754199),
(38348, 'Leviticus 26:16', 'Leviticus', 26, 16, 'نو زه به تاسو ته داسې سزا درکړم: په تاسو باندې به افت نازل کړم، داسې ناروغي چې د علاج وړ نه وي او تبې چې تاسو به ړانده کړي او ستاسو ژوند به خراب کړي. تاسو به خپل فصلونه وکرئ، خو هېڅ ګټه به درته ونه رسوي، ځکه چې څه چې تاسو کرئ ستاسو دښمنان به یې وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_16.mp3', '', 1761754199, 1761754199),
(38349, 'Leviticus 26:17', 'Leviticus', 26, 17, 'زه به ستاسو په خلاف شم، ترڅو ستاسو دښمنان تاسو ته ماتې درکړي او هغوی چې ستاسو څخه کرکه کوي، په تاسو باندې به حکومت کوي. تاسو به دومره وېرېږئ چې بې له دې چې څوک مو تعقیب کړي، تاسو به تښتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_17.mp3', '', 1761754199, 1761754199),
(38350, 'Leviticus 26:18', 'Leviticus', 26, 18, 'که چېرې د دغو ټولو شیانو څخه وروسته بیاهم ماته غوږ ونه نیسئ، زه به تاسو ته ستاسو د ګناهونو په خاطر اووه چنده زیاته سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_18.mp3', '', 1761754199, 1761754199),
(38351, 'Leviticus 26:19', 'Leviticus', 26, 19, 'زه به ستاسو سخت غرور مات کړم. هېڅ باران به نه وي او ستاسو ځمکه به وچه شي او د اوسپنې په شان به کلکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_19.mp3', '', 1761754199, 1761754199),
(38352, 'Leviticus 26:20', 'Leviticus', 26, 20, 'ستاسو ټول زیار او زحمت به تاسو ته هېڅ ګټه ونه رسوي، ځکه چې ستاسو ځمکه به فصلونه نه کوي او ونې به مېوه ونه نیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_20.mp3', '', 1761754199, 1761754199),
(38353, 'Leviticus 26:21', 'Leviticus', 26, 21, 'که چېرې تاسو زما په خلاف اوسئ او ماته غوږ ونه نیسئ، زه به بیا ستاسو سزا اووه چنده زیاته کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_21.mp3', '', 1761754199, 1761754199),
(38354, 'Leviticus 26:22', 'Leviticus', 26, 22, 'زه به ستاسو منځ ته وحشي حیوانات درولېږم او هغوی به ستاسو اولادونه ووژني، ستاسو حیوانات به له منځه یوسي او ستاسو شمېر به دومره کم کړي چې لارې به مو خوشې پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_22.mp3', '', 1761754199, 1761754199),
(38355, 'Leviticus 26:23', 'Leviticus', 26, 23, 'که چېرې د دغو ټولو سزاګانو سره سره زما خبرو ته غوږ ونه نیسئ او زما په خلاف پاتې شئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_23.mp3', '', 1761754199, 1761754199),
(38356, 'Leviticus 26:24', 'Leviticus', 26, 24, 'زه به په خپله ستاسو په خلاف شم او تاسو ته به له مخکې څخه اووه چنده سخته سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_24.mp3', '', 1761754199, 1761754199),
(38357, 'Leviticus 26:25', 'Leviticus', 26, 25, 'زه به په تاسو باندې جنګ راولم د دې په خاطر چې تاسو ته د خپل لوظ د ماتولو دپاره سزا درکړم او که چېرې تاسو د خوندي پاتې کېدلو دپاره په خپلو ښارونو کې راټول شئ، زه به په تاسو باندې ناعلاجه ناروغۍ نازلې کړم او تاسو به مجبور شئ چې خپلو دښمنانو ته تسلیم شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_25.mp3', '', 1761754199, 1761754199),
(38358, 'Leviticus 26:26', 'Leviticus', 26, 26, 'زه به په تاسو باندې خواړه بند کړم چې لس ښځې به په یو تنور ډوډۍ پخوي. ستاسو جیره به دومره کمه کړم چې کله تاسو هغه ټوله وخورئ، بیا به هم ماړه نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_26.mp3', '', 1761754199, 1761754199),
(38359, 'Leviticus 26:27', 'Leviticus', 26, 27, 'که چېرې له دې سره سره بیاهم تاسو ماته غوږ ونه نیسئ او زما په خلاف پاتې شئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_27.mp3', '', 1761754199, 1761754199),
(38360, 'Leviticus 26:28', 'Leviticus', 26, 28, 'بیا به زه په تاسو باندې خپل غضب نازل کړم او ستاسو سزا به له پخوا څخه اووه چنده زیاته کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_28.mp3', '', 1761754199, 1761754199),
(38361, 'Leviticus 26:29', 'Leviticus', 26, 29, 'ستاسو لوږه به دومره زیاته شي چې خپل اولادونه به وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_29.mp3', '', 1761754199, 1761754199),
(38362, 'Leviticus 26:30', 'Leviticus', 26, 30, 'زه به ستاسو سیمه ییز عبادت ځایونه او د خوشبویۍ د سوځولو ځایونه له منځه یوسم. مړي به مو ستاسو په بې ساه بتانو باندې وغورځوم. زه به ستاسو څخه کرکه وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_30.mp3', '', 1761754199, 1761754199),
(38363, 'Leviticus 26:31', 'Leviticus', 26, 31, 'ستاسو ښارونه به په کنډوالو بدل کړم، ستاسو عبادت ځایونه به له منځه یوسم او ستاسو قربانۍ به قبولې نه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_31.mp3', '', 1761754199, 1761754199),
(38364, 'Leviticus 26:32', 'Leviticus', 26, 32, 'زه به ستاسو وطن داسې وران کړم چې کله ستاسو دښمنان هغه ونیسي، نو دې ورانۍ ته به هک حیران پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_32.mp3', '', 1761754199, 1761754199),
(38365, 'Leviticus 26:33', 'Leviticus', 26, 33, 'زه به په تاسو باندې جنګ راولم او تاسو به په پردیو هېوادونو کې خپاره کړم. ستاسو ځمکه به خوشې پاتې شي او ښارونه به مو په کنډوالو بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_33.mp3', '', 1761754199, 1761754199),
(38366, 'Leviticus 26:36', 'Leviticus', 26, 36, 'ستاسو هغه خلک چې په جلاوطنۍ کې دي، د هغوی په زړونو کې به داسې وېره واچوم چې د هغې پاڼې له اواز څخه به هم تښتي چې باد یې رپوي. هغوی به داسې منډې وهي لکه څوک چې یې په جګړه کې تعقیبوي. د هغوی په څنګ کې به هېڅ دښمن نه وي، خو هغوی به غورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_36.mp3', '', 1761754199, 1761754199),
(38367, 'Leviticus 26:37', 'Leviticus', 26, 37, 'هېڅ څوک به هغوی نه تعقیبوي، خو هغوی به د یو بل دپاسه غورځیږي او دا توان به نه لري چې د خپلو دښمنانو په وړاندې ودریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_37.mp3', '', 1761754199, 1761754199),
(38368, 'Leviticus 26:38', 'Leviticus', 26, 38, 'هغوی به په پردي وطن کې مړه شي او د خپلو دښمنانو خاوره به یې ژوندي تېر کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_38.mp3', '', 1761754199, 1761754199),
(38369, 'Leviticus 26:39', 'Leviticus', 26, 39, 'د هغوی څخه چې څوک د خپلو دښمنانو په خاوره کې ژوندي پاتې شي، د هغوی ژوند به ستاسو او ستاسو د نیکونو د ګناه له امله برباد شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_39.mp3', '', 1761754199, 1761754199),
(38370, 'Leviticus 26:40', 'Leviticus', 26, 40, 'خو ستاسو اولاده به د خپلو ګناهونو او خپلو نیکونو د ګناهونو اقرار کوي چې زما سره یې بې وفایي او دښمني وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_40.mp3', '', 1761754199, 1761754199),
(38371, 'Leviticus 26:41', 'Leviticus', 26, 41, 'او زه یې د خپل ځان په خلاف کړم، ترڅو هغوی د خپلو دښمنانو خاورې ته وشړم. په اخر کې کله چې ستاسو د اولادې سخت زړونه نرم شي او د خپلې ګناه دپاره سزا ومومي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_41.mp3', '', 1761754199, 1761754199),
(38372, 'Leviticus 26:42', 'Leviticus', 26, 42, 'زه به د یعقوب، اسحاق او ابراهیم سره خپل لوظ او خپل قوم ته د ځمکې د ورکولو وعده رایاده کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_42.mp3', '', 1761754199, 1761754199),
(38373, 'Leviticus 26:43', 'Leviticus', 26, 43, 'لومړی باید د دې وطن خلک دا ځمکه پرېږدي، ترڅو د شاړې پاتې کېدلو څخه ګټه واخلي او هغوی باید زما د قوانینو او فرمانونو د ردولو په سبب د خپلو ګناهونو پوره بیه ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_43.mp3', '', 1761754199, 1761754199),
(38374, 'Leviticus 26:44', 'Leviticus', 26, 44, 'بیاهم، کله چې هغوی د خپلو دښمنانو په خاوره کې وي، زه به یې بیخي له منځه نه وړم. هغوی به نه پرېږدم او خپل لوظ به ورسره مات نه کړم، ځکه چې زه د هغوی څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_44.mp3', '', 1761754199, 1761754199),
(38375, 'Leviticus 26:45', 'Leviticus', 26, 45, 'خو زه به د هغوی په خاطر هغه لوظ رایاد کړم چې د هغوی د نیکونو سره مې هغه وخت کړی ؤ چې هغوی مې د مصر څخه راوویستل، د دې دپاره چې زه به د هغوی خدای اوسم او په دې ډول مې نورو قومونو ته خپل قدرت وروښود.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_45.mp3', '', 1761754199, 1761754199),
(38376, 'Leviticus 26:46', 'Leviticus', 26, 46, 'دا هغه فرمانونه، قوانین او مقررات دي چې څښتن د سینا په غره باندې د اسراییلیانو دپاره موسی ته ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus26_verse_46.mp3', '', 1761754199, 1761754199),
(38377, 'Numbers 12:1', 'Numbers', 12, 1, 'موسی د یوې ایتوپیایۍ ښځې سره واده کړی ؤ او مریم او هارون په هغه باندې د دې کار په خاطر انتقاد وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_1.mp3', '', 1761754199, 1761754199),
(38378, 'Numbers 12:2', 'Numbers', 12, 2, 'هغوی وویل: «ایا څښتن یوازې د موسی په وسیله خبرې کړې دي؟ ایا هغه زمونږ په وسیله خبرې نه دي کړي؟» څه چې هغوی وویل څښتن هغه واورېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_2.mp3', '', 1761754199, 1761754199),
(38379, 'Numbers 12:3', 'Numbers', 12, 3, '(موسی د ځمکې په مخ تر ټولو عاجز سړی ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_3.mp3', '', 1761754199, 1761754199),
(38380, 'Numbers 12:4', 'Numbers', 12, 4, 'څښتن سمدلاسه موسی، هارون او مریم ته وویل: «زه غواړم چې تاسو درې واړه سپېڅلې خېمې ته راشئ.» نو هغوی ورغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_4.mp3', '', 1761754199, 1761754199),
(38381, 'Numbers 12:5', 'Numbers', 12, 5, 'څښتن د ستنې په شان ورېځ کې راښکته شو، د خېمې د دروازې په خوله کې ودرېده او غږ یې وکړ: «ای هارونه! ای مریمې!» هغوی دواړه رامخکې شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_5.mp3', '', 1761754199, 1761754199),
(38382, 'Numbers 12:6', 'Numbers', 12, 6, 'او څښتن وویل: «اوس زما خبرې ته غوږ ونیسئ! زه خپل ځان نبیانو ته په رویاګانو کې ښکاره کوم او د هغوی سره په خوبونو کې خبرې کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_6.mp3', '', 1761754199, 1761754199),
(38383, 'Numbers 12:7', 'Numbers', 12, 7, 'خو کله چې د خپل خدمتګار موسی سره خبرې کوم هغه د نورو سره فرق لري. هغه مې د خپل ټول قوم مشر ټاکلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_7.mp3', '', 1761754199, 1761754199),
(38384, 'Numbers 12:8', 'Numbers', 12, 8, 'نو زه د هغه سره مخامخ او صفا خبرې کوم، نه په پټه، حتی که هغه زما څېره هم ویني! تاسو څنګه جرات کوئ چې زما د خدمتګار موسی په ضد خبرې وکړئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_8.mp3', '', 1761754199, 1761754199),
(38385, 'Numbers 12:9', 'Numbers', 12, 9, 'څښتن په هارون او مریم باندې په قهر شو. د څښتن د تګ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_9.mp3', '', 1761754199, 1761754199),
(38386, 'Numbers 12:10', 'Numbers', 12, 10, 'او د سپېڅلې خېمې د سر څخه د ورېځې د لېرې کېدلو څخه وروسته مریم په جذام باندې اخته شوه او پوستکی یې لکه د واورې په شان سپین واوښت. کله چې هارون هغې ته وکتل، نو ویې لیدل چې هغه په جذام باندې اخته شوې ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_10.mp3', '', 1761754199, 1761754199),
(38387, 'Numbers 12:11', 'Numbers', 12, 11, 'نو موسی ته یې وویل: «زما باداره، مونږ ته د داسې ګناه په خاطر چې په بې عقلۍ سره مو کړې ده، سزا مه راکوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_11.mp3', '', 1761754199, 1761754199),
(38388, 'Numbers 12:12', 'Numbers', 12, 12, 'مه پرېږده چې د مریم غوښه د یو مړ زېږېدلي ماشوم په شان خوسا شي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_12.mp3', '', 1761754199, 1761754199),
(38389, 'Numbers 12:13', 'Numbers', 12, 13, 'نو موسی څښتن ته فریاد وکړ: «ای خدایه، هغه روغه کړه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_13.mp3', '', 1761754199, 1761754199),
(38390, 'Numbers 12:14', 'Numbers', 12, 14, 'خو څښتن په ځواب کې وویل: «که چېرې پلار یې د هغې په مخ باندې لیاړې توکړې وای، نو هغه به اووه ورځې خجالت نه وای؟ نو پرېږده چې یوه هفته د کمپ څخه دباندې ایساره وي او له هغې وروسته کېدای شي چې کمپ ته راوستل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_14.mp3', '', 1761754199, 1761754199),
(38391, 'Numbers 12:15', 'Numbers', 12, 15, 'مریم اووه ورځې د کمپ څخه دباندې ایساره پاتې شوه او قوم تر هغه وخته پورې حرکت ونه کړ، ترڅو هغه بېرته کمپ ته راوستل شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_15.mp3', '', 1761754199, 1761754199),
(38392, 'Numbers 12:16', 'Numbers', 12, 16, 'بیا هغوی د حضیروت څخه لاړل او د فاران په دښته کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers12_verse_16.mp3', '', 1761754199, 1761754199),
(38393, 'Psalms 146:1', 'Psalms', 146, 1, 'د څښتن ثنا او صفت وکړئ ووایه ثنا د څښتن ای زما ځانه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_1.mp3', '', 1761754199, 1761754199),
(38394, 'Psalms 146:2', 'Psalms', 146, 2, 'ترڅو ژوندی یم زه به وایمه ثنا د هغه زه به خپل خدای ته ټول عمر سندرې وایم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_2.mp3', '', 1761754199, 1761754199),
(38395, 'Psalms 146:3', 'Psalms', 146, 3, 'په قدرتمندو خلکو تاسو توکل مه کوئ هېڅ فاني انسان تاسو ژغورلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_3.mp3', '', 1761754199, 1761754199),
(38396, 'Psalms 146:4', 'Psalms', 146, 4, 'کله چې مړه شي هغوی، بېرته ورځي خاورو ته په هغه ورځ به شي برباد ټولې نقشې د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_4.mp3', '', 1761754199, 1761754199),
(38397, 'Psalms 146:5', 'Psalms', 146, 5, 'بختور دی هغه څوک چې مددګار یې دی خدای د یعقوب چې یې امید په خپل څښتن خدای باندې وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_5.mp3', '', 1761754199, 1761754199),
(38398, 'Psalms 146:6', 'Psalms', 146, 6, 'چې دی خالق د اسمان، ځمکې او دریابونو او هرڅه چې دي هغو کې چې ولاړ وي همېشه خپلو وعدو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_6.mp3', '', 1761754199, 1761754199),
(38399, 'Psalms 146:7', 'Psalms', 146, 7, 'چې انصاف کوي د مظلومانو سره او وږیو خلکو ته خواړه ورکوي څښتن بندیان ازادوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_7.mp3', '', 1761754199, 1761754199),
(38400, 'Psalms 146:8', 'Psalms', 146, 8, 'او بینا کوي ړانده لاس ورکوي کړوپ شویو خلکو ته د نېکو خلکو سره مینه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_8.mp3', '', 1761754199, 1761754199),
(38401, 'Psalms 146:9', 'Psalms', 146, 9, 'هغه ساتنه کوي د پردو خلکو هغه پام کوي په کونډو او یتیمانو باندې خو خرابوي د بدکارانو پلانونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_9.mp3', '', 1761754199, 1761754199),
(38402, 'Psalms 146:10', 'Psalms', 146, 10, 'څښتن به کړي پاچاهي د تل دپاره ای صهیونه، پاچاهي به کړي ستا خدای ټولو نسلونو پورې د څښتن ثنا او صفت وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms146_verse_10.mp3', '', 1761754199, 1761754199),
(38403, 'Isaiah 10:1', 'Isaiah', 10, 1, 'افسوس ستاسو په حال! تاسو د بې عدالتۍ قوانین جوړوئ او لیکل شوې پرېکړې مو د ظلم په بنیاد ولاړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_1.mp3', '', 1761754199, 1761754199),
(38404, 'Isaiah 10:2', 'Isaiah', 10, 2, 'په دې ډول تاسو نه پرېږدئ چې بې وزلي خپل حقونه تر لاسه کړي او د هغوی سره انصاف او عدالت وشي. په دې ډول تاسو د کونډو او یتیمانو شتمني لوټوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_2.mp3', '', 1761754199, 1761754199),
(38405, 'Isaiah 10:3', 'Isaiah', 10, 3, 'نو تاسو به د سزا په ورځ څه کوئ؟ کله چې خدای د کوم لېرې وطن نه په تاسو باندې مصیبت راولي، نو تاسو به څه کوئ؟ تاسو به د مرستې په خاطر چېرته منډې وهئ؟ خپله شتمني به چېرته پټوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_3.mp3', '', 1761754199, 1761754199),
(38406, 'Isaiah 10:4', 'Isaiah', 10, 4, 'تاسو یا په جګړه کې وژل کېږئ، او یا تاسو اسیر نیول کېږئ. خو بیاهم د څښتن قهر لا نه دی سوړ شوی، د هغه لاس لا تر اوسه د سزا ورکولو دپاره اوچت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_4.mp3', '', 1761754199, 1761754199),
(38407, 'Isaiah 10:5', 'Isaiah', 10, 5, 'څښتن وویل: «افسوس ستا په حال ای اشوره! زه ستا نه د یو لرګي په توګه کار اخلم چې په تا هغو خلکو ته سزا ورکړم چې زه ورباندې په قهر یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_5.mp3', '', 1761754199, 1761754199),
(38408, 'Isaiah 10:6', 'Isaiah', 10, 6, 'زه اشوریان لېږم چې په هغه بې ایمانه قوم باندې چې زه یې په قهر کړی یم، حمله وکړي. زه اشوریان لېږم چې د هغوی مالونه لوټ کړي او په غنیمت یې ونیسي، په خپله دوی لکه د کوڅو د خاورو په شان تر پښو لاندې کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_6.mp3', '', 1761754199, 1761754199),
(38409, 'Isaiah 10:7', 'Isaiah', 10, 7, 'خو د اشور د پاچا په زړه کې د تاو تریخوالي نورې نقشې دي. هغه غواړي چې ډېر قومونه له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_7.mp3', '', 1761754199, 1761754199),
(38410, 'Isaiah 10:8', 'Isaiah', 10, 8, 'هغه وایي: «زما هر یو قوماندان پاچا دی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah10_verse_8.mp3', '', 1761754199, 1761754199);